#!/usr/bin/env python3
"""Render the combined QA candidates as an offline, reviewer-editable HTML file."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
REVIEW = ROOT / "all_qa_review_drafts_v1"
rows = [json.loads(x) for x in (REVIEW / "all_qa_drafts.jsonl").read_text().splitlines() if x]
payload = json.dumps(rows, ensure_ascii=False).replace("</", "<\\/")

page = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>All QA review candidates</title><style>
:root{--bg:#09111f;--card:#111f35;--line:#294465;--ink:#eaf3ff;--muted:#9eb3cf;--blue:#73c7ff;--ok:#3bd49b;--warn:#ffc857;--bad:#ff758f}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}header{position:sticky;top:0;z-index:5;padding:15px 22px;background:#0b1628f2;border-bottom:1px solid var(--line);backdrop-filter:blur(10px)}h1{font-size:20px;margin:0}.sub{margin:5px 0;color:var(--muted)}.tools{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}input,select,button,textarea{font:inherit;color:var(--ink);background:#0e1c31;border:1px solid var(--line);border-radius:7px;padding:7px 9px}input{min-width:270px}button{cursor:pointer}button:hover{border-color:var(--blue)}main{max-width:1280px;margin:auto;padding:18px}.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px;margin:12px 0}.card.ACCEPT{border-color:var(--ok)}.card.REVISE,.card.FLAG{border-color:var(--warn)}.card.REJECT{border-color:var(--bad)}.meta,.tags{display:flex;gap:7px;flex-wrap:wrap;color:var(--muted);font-size:13px}.tag{border:1px solid var(--line);border-radius:999px;padding:2px 8px}.q{font-size:18px;font-weight:650;margin:12px 0 7px}.answer{background:#0b182b;border-left:3px solid var(--blue);padding:10px;border-radius:4px;white-space:pre-wrap}.evidence{margin-top:12px}.unit{border-top:1px solid var(--line);padding:10px 0}.quote{white-space:pre-wrap;color:#dbeaff}.path{font:12px ui-monospace,monospace;color:var(--muted);word-break:break-all}.review{display:grid;grid-template-columns:180px 1fr;gap:8px;margin-top:14px}.issues{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}.issues label{font-size:13px;border:1px solid var(--line);border-radius:999px;padding:3px 7px;color:var(--muted)}.issues input{min-width:auto;padding:0}.empty{padding:30px;color:var(--muted);text-align:center}@media(max-width:700px){header{padding:13px}.review{grid-template-columns:1fr}input{width:100%;min-width:0}}
</style></head><body><header><h1>全部 Query / Candidate Gold 审阅</h1><p class="sub">标记保存在此浏览器；点击“导出”获得可回传 JSON。所有答案仍须人工批准后才是正式 gold。</p><div class="tools"><input id="search" placeholder="搜索问题、答案、证据或文档"><select id="corpus"><option value="">全部语料</option></select><select id="doc"><option value="">全部文档</option></select><select id="status"><option value="">全部状态</option><option>UNREVIEWED</option><option>ACCEPT</option><option>REVISE</option><option>FLAG</option><option>REJECT</option></select><button id="prev">上一页</button><button id="next">下一页</button><button id="export">导出标记 JSON</button><button id="clear">清除本地标记</button></div><p id="count" class="sub"></p></header><main id="cards"></main><script>
const rows=__PAYLOAD__,KEY='dynamic-edge-all-qa-review-v1',PAGE_SIZE=15; let pageNo=0,state={}; try{state=JSON.parse(localStorage.getItem(KEY)||'{}')}catch(e){console.warn('Local review storage unavailable; export your decisions before reloading.',e)}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); const docs=[...new Set(rows.map(r=>r.document_id))].sort(),corpora=[...new Set(rows.map(r=>r.corpus))].sort();
for(const [id,vals] of [['doc',docs],['corpus',corpora]])for(const v of vals)document.querySelector('#'+id).insertAdjacentHTML('beforeend',`<option value="${esc(v)}">${esc(v)}</option>`);
const get=r=>state[r.draft_id]||{}, status=r=>get(r).status||'UNREVIEWED'; const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){console.warn('Local review storage unavailable; use Export review JSON.',e)}};
function render(){const q=search.value.toLowerCase(),c=corpus.value,d=doc.value,s=statusSel.value;const visible=rows.filter(r=>{const hay=[r.question,r.gold_answer_draft,r.document_id,...r.gold_evidence_draft.map(e=>e.text)].join(' ').toLowerCase();return(!q||hay.includes(q))&&(!c||r.corpus===c)&&(!d||r.document_id===d)&&(!s||status(r)===s)});const pages=Math.max(1,Math.ceil(visible.length/PAGE_SIZE));pageNo=Math.min(pageNo,pages-1);const shown=visible.slice(pageNo*PAGE_SIZE,(pageNo+1)*PAGE_SIZE);count.textContent=`显示 ${visible.length} / ${rows.length} 条 · 第 ${pageNo+1}/${pages} 页 · 已接受 ${rows.filter(r=>status(r)==='ACCEPT').length} · 已标记问题 ${rows.filter(r=>status(r)==='FLAG').length}`;cards.innerHTML=shown.length?shown.map(r=>{const rv=get(r),ev=r.gold_evidence_draft.map(e=>`<div class="unit"><div class="tags"><span class="tag">${esc(e.evidence_unit_id)}</span><span class="tag">${esc(e.page_number??e.page_id)}</span><span class="tag">${esc(e.element_type)}</span></div><div class="quote">${esc(e.text)}</div><div class="path">${esc(e.source_json||e.source_node_file||'')}</div>${e.source_page_image?`<div class="path">page image: ${esc(e.source_page_image)}</div>`:''}</div>`).join('');const issue=['unsupported_answer','weak_evidence','ambiguous_question','too_easy','too_hard','duplicate','other'].map(x=>`<label><input type="checkbox" data-id="${esc(r.draft_id)}" data-issue="${x}" ${(rv.issues||[]).includes(x)?'checked':''}> ${x}</label>`).join('');return `<article class="card ${esc(status(r))}"><div class="meta"><span class="tag">${esc(r.draft_id)}</span><span class="tag">${esc(r.corpus)}</span><span class="tag">${esc(r.document_id)}</span><span class="tag">${esc(r.question_type_actual)}</span></div><div class="q">${esc(r.question)}</div><div class="answer"><b>Candidate gold answer</b><br>${esc(r.gold_answer_draft)}</div><div class="evidence"><b>Evidence</b>${ev}</div><div class="review"><select class="decision" data-id="${esc(r.draft_id)}"><option>UNREVIEWED</option><option>ACCEPT</option><option>REVISE</option><option>FLAG</option><option>REJECT</option></select><textarea class="notes" data-id="${esc(r.draft_id)}" placeholder="直接写下要修改什么、答案哪里不对、应补什么证据…">${esc(rv.notes||'')}</textarea></div><div class="issues">${issue}</div></article>`}).join(''):'<p class="empty">没有符合筛选条件的条目。</p>';document.querySelectorAll('.decision').forEach(x=>{x.value=status({draft_id:x.dataset.id});x.onchange=()=>{state[x.dataset.id]={...(state[x.dataset.id]||{}),status:x.value,updated_at:new Date().toISOString()};save();render()}});document.querySelectorAll('.notes').forEach(x=>x.oninput=()=>{state[x.dataset.id]={...(state[x.dataset.id]||{}),notes:x.value,updated_at:new Date().toISOString()};save()});document.querySelectorAll('[data-issue]').forEach(x=>x.onchange=()=>{let a=state[x.dataset.id]||{};let z=new Set(a.issues||[]);x.checked?z.add(x.dataset.issue):z.delete(x.dataset.issue);state[x.dataset.id]={...a,issues:[...z],updated_at:new Date().toISOString()};save()});}
const search=document.querySelector('#search'),corpus=document.querySelector('#corpus'),doc=document.querySelector('#doc'),statusSel=document.querySelector('#status'),count=document.querySelector('#count'),cards=document.querySelector('#cards');[search,corpus,doc,statusSel].forEach(x=>x.oninput=x.onchange=()=>{pageNo=0;render()});document.querySelector('#prev').onclick=()=>{pageNo=Math.max(0,pageNo-1);render();scrollTo(0,0)};document.querySelector('#next').onclick=()=>{pageNo++;render();scrollTo(0,0)};document.querySelector('#export').onclick=()=>{const out=rows.map(r=>({...r,review:{status:status(r),issues:get(r).issues||[],notes:get(r).notes||'',updated_at:get(r).updated_at||null}}));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));a.download='all_qa_review_decisions.json';a.click();URL.revokeObjectURL(a.href)};document.querySelector('#clear').onclick=()=>{if(confirm('清除本浏览器的全部审阅标记？')){try{localStorage.removeItem(KEY)}catch(e){} location.reload()}};render();
</script></body></html>'''.replace('__PAYLOAD__', payload)
(REVIEW / 'review.html').write_text(page, encoding='utf-8')
print(f'Wrote {REVIEW / "review.html"} with {len(rows)} drafts')
